import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1_000_000_007;

    static long inverseMod(long x) {
        long exp = MOD - 2;
        long res = 1;
        long base = x;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    public void process() {
        long[] fact = new long[51];
        fact[0] = 1;
        for (int i = 1; i < 51; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        long[][] combs = new long[51][51];
        for (int i = 0; i <= 50; i++) combs[i][0] = 1;
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= i; j++) {
                combs[i][j] = (fact[i] * inverseMod((fact[j] * fact[i - j]) % MOD)) % MOD;
            }
        }

        Scanner sc = new Scanner(System.in);
        int totalCards = sc.nextInt();
        int maxCards = sc.nextInt();
        int c50Count = 0, c100Count = 0;
        for (int i = 0; i < totalCards; i++) {
            int val = sc.nextInt();
            if (val == 100) c100Count++;
            else c50Count++;
        }

        Node[][][] graphNodes = new Node[c50Count + 1][c100Count + 1][2];
        for (int i = 0; i <= c50Count; i++) {
            for (int j = 0; j <= c100Count; j++) {
                graphNodes[i][j][0] = new Node(i, j, 0);
                graphNodes[i][j][1] = new Node(i, j, 1);
            }
        }

        for (int i = 0; i <= c50Count; i++) {
            for (int j = 0; j <= c100Count; j++) {
                int max50Pick = Math.min(maxCards / 50, i);
                int max100Pick = Math.min(maxCards / 100, j);
                for (int x = max100Pick; x >= 0; x--) {
                    for (int y = Math.min(max50Pick, (maxCards - 100 * x) / 50); y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        graphNodes[i][j][0].s.add(graphNodes[i - y][j - x][1]);
                        graphNodes[i - y][j - x][1].s.add(graphNodes[i][j][0]);
                    }
                }
            }
        }

        Queue<Node> q = new LinkedList<>();
        graphNodes[c50Count][c100Count][0].n = 1;
        graphNodes[c50Count][c100Count][0].am = 1;
        q.offer(graphNodes[c50Count][c100Count][0]);

        while (!q.isEmpty()) {
            Node current = q.poll();
            for (Node neighbor : current.s) {
                if (neighbor.n == 0 || neighbor.n == current.n + 1) {
                    long p1 = combs[current.b == 0 ? current.c50 : c50Count - current.c50][Math.abs(current.c50 - neighbor.c50)];
                    long p2 = combs[current.b == 0 ? current.c100 : c100Count - current.c100][Math.abs(current.c100 - neighbor.c100)];
                    neighbor.am = (neighbor.am + (current.am * (p1 * p2) % MOD)) % MOD;
                    if (neighbor.n == 0) {
                        neighbor.n = current.n + 1;
                        q.offer(neighbor);
                    }
                }
            }
        }

        System.out.println((graphNodes[0][0][1].n - 1) + "\n" + graphNodes[0][0][1].am);
    }

    class Node {
        int c50, c100, b, n;
        long am;
        List<Node> s;
        Node(int c50, int c100, int b) {
            this.c50 = c50;
            this.c100 = c100;
            this.b = b;
            this.s = new ArrayList<>();
            this.n = 0;
            this.am = 0;
        }
    }

    public static void main(String[] args) {
        new Main().process();
    }
}
